export class FX{constructor(){this.flash=0;this.bloom=0;this.vignette=.35;this.particles=[]}burst(x,y,n=28){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=80+Math.random()*260;this.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.45})}}update(dt){this.flash=Math.max(0,this.flash-dt*4);for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt}this.particles=this.particles.filter(p=>p.life>0)}draw(ctx,w,h){for(const p of this.particles){ctx.globalAlpha=Math.max(0,p.life/.45);ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1;const g=ctx.createRadialGradient(w/2,h/2,Math.min(w,h)*.15,w/2,h/2,Math.max(w,h)*.7);g.addColorStop(0,'transparent');g.addColorStop(1,`rgba(0,0,0,${this.vignette})`);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);if(this.flash){ctx.fillStyle=`rgba(255,255,255,${this.flash})`;ctx.fillRect(0,0,w,h)}}}